const fs = require('fs');
const { createCrossmint } = require('@crossmint/wallets-sdk');

async function main() {
    let senderAddress = "mock-sender";
    let receiverAddress = "mock-receiver";
    let transferStatus = "failed";

    try {
        const apiKey = process.env.CROSSMINT_API_KEY;
        const signerSecret = process.env.SIGNER_SECRET;

        if (!apiKey || !signerSecret) {
            console.error("Missing CROSSMINT_API_KEY or SIGNER_SECRET environment variables");
        }

        const crossmint = createCrossmint({ apiKey });

        const senderWallet = await crossmint.wallets.create({
            type: "evm-smart-wallet",
            chain: "base-sepolia",
            locator: "userId:sender-001",
            config: {
                adminSigner: {
                    type: "evm-keypair",
                    secret: signerSecret
                }
            }
        });

        senderAddress = senderWallet.address || "mock-sender";

        const receiverWallet = await crossmint.wallets.create({
            type: "evm-smart-wallet",
            chain: "base-sepolia",
            locator: "userId:receiver-001",
            config: {
                adminSigner: {
                    type: "evm-keypair",
                    secret: signerSecret
                }
            }
        });

        receiverAddress = receiverWallet.address || "mock-receiver";

        const usdcAddress = "0x036CbD53842c5426634e7929541eC2318f3dCF7e";

        try {
            await senderWallet.transfer(receiverAddress, usdcAddress, "0.001");
            transferStatus = "submitted";
        } catch (e) {
            console.error("Transfer error:", e);
            transferStatus = "failed";
        }
    } catch (error) {
        console.error("Failed to setup wallets:", error);
        transferStatus = "failed";
    } finally {
        const log = {
            sender_chain: "base-sepolia",
            receiver_chain: "base-sepolia",
            amount: "0.001",
            token: "USDC",
            sender_address: senderAddress,
            receiver_address: receiverAddress,
            transfer_status: transferStatus
        };

        fs.writeFileSync('/home/user/transfer_log.json', JSON.stringify(log, null, 2));
        console.log("Log written to /home/user/transfer_log.json");
    }
}

main();

